Need to create script PlayerController with WASD movement. Use manage_script create. Provide contents.<|channel|>final <|constrain|>JSON array<|message|>[
  {
    "function": "manage_script",
    "args": {
      "action": "create",
      "name": "PlayerController",
      "path": "Assets/Scripts/",
      "contents": "using UnityEngine;\n\npublic class PlayerController : MonoBehaviour {\n    public float speed = 5f;\n    void Update() {\n        float h = Input.GetAxisRaw(\"Horizontal\"); // A/D or Left/Right\n        float v = Input.GetAxisRaw(\"Vertical\");   // W/S or Up/Down\n        Vector3 move = new Vector3(h, 0, v).normalized * speed * Time.deltaTime;\n        transform.Translate(move, Space.World);\n    }\n}"
    }
  }
]

Need create script, add to player GameObject. Assume player exists named "Player". Use manage_script create and then modify gameobject to add component.<|channel|>final <|constrain|>JSON array of commands<|message|>[
  {
    "function": "manage_script",
    "args": {
      "action": "create",
      "name": "PlayerController",
      "path": "Assets/Scripts/",
      "contents": "using UnityEngine;\n\npublic class PlayerController : MonoBehaviour {\n    public float speed = 5.0f;\n    void Update() {\n        float horizontal = Input.GetAxis(\"Horizontal\");\n        float vertical = Input.GetAxis(\"Vertical\");\n        Vector3 direction = new Vector3(horizontal, 0, vertical).normalized;\n        transform.Translate(direction * speed * Time.deltaTime);\n    }\n}"
    }
  },
  {
    "function": "manage_gameobject",
    "args": {
      "action": "add_component",
      "target": "Player",
      "components_to_add": ["PlayerController"]
    }
  },
  {
    "function": "manage_editor",
    "args": {
      "action": "play"
    }
  }
]

